    whatsNewNotoTitle: "움직이는 기본 아이콘",
    whatsNewNotoBody: "Noto 움직이는 이모지 두 묶음이 처음부터 있어요. Room 채팅에서도 보낼 수 있어요.",
    whatsNewIconSaleTitle: "아이콘 만들고 팔기",
    whatsNewIconSaleBody: "‘✏️ 만들기’로 사진·글자·스티커를 겹쳐 움직이는 아이콘을 만들고, 묶음을 2~30P에 팔 수 있어요. 많이 쓰는 묶음엔 🔥가 붙어요.",
    whatsNewScriptsTitle: "단계마다 상황",
    whatsNewScriptsBody: "My의 단계마다 상황이 있어요. 듣고 내 줄을 말해요 — 모두 통과하면 다음 단계가 열려요.",
    whatsNewFramesTitle: "문장구조·다시 연습",
    whatsNewFramesBody: "문장구조 하나를 빈칸만 바꿔 네 번 말해요. 튜터가 같은 문장구조를 두 번 고치면 ‘다시 연습’으로 돌아와요.",
    whatsNewAiTutorTitle: "사람 탭의 AI 튜터",
    whatsNewAiTutorBody: "AI 튜터가 사람 탭 맨 위에 있어요. 프로필에서 메시지·통화·통화 기록을 열어요.",
    whatsNewTodayTitle: "매일 할 것을 정해 줘요",
    whatsNewTodayBody: "하루 분량을 고르면 며칠에 끝나는지 보여 주고, 헷갈린 곳은 짧은 퀴즈로 다시 나와요.",
    whatsNewKeepTitle: "틈틈이 지속 학습",
    whatsNewKeepBody: "‘지속 학습’에서 랜덤·어휘·문법·표현을 골라 짧은 퀴즈를 풀어요. 틀린 줄과 튜터가 고친 줄은 아래 ‘복습’에 모여요.",
    whatsNewLettersTitle: "0단계와 읽는 법",
    whatsNewLettersBody: "글자가 다른 언어는 0단계 글자·소리부터, ‘읽는 법’을 켜면 줄마다 읽는 법이 나와요.",
    whatsNewMissedTitle: "틀린 것을 다시 보여 줘요",
    whatsNewMissedBody: "튜터가 고친 줄과 상황에서 틀린 줄이 My ‘복습’에 모이고, 아침 알림으로 잠금화면에도 떠요.",
    whatsNewStagePartsTitle: "어휘·문법·표현·발음으로 보는 단계",
    whatsNewStagePartsBody: "My가 어휘·문법·표현·발음 네 칸으로 바뀌었어요. 가장 부족한 칸을 바로 연습하고, 네 칸이 70%를 넘으면 ‘다음 단계로’. 단계마다 할 수 있는 대화 예시도 있어요.",
    whatsNewBoardTopicsTitle: "게시판 주제 칩",
    whatsNewBoardTopicsBody: "배우는 언어 게시판을 자유·질문·메이트·보이스룸·단체방으로 골라 봐요. 보이스룸·단체방 글에서 ‘들어가기’·‘참여하기’로 바로 가요.",
    whatsNewGamesTitle: "Room에서 게임",
    whatsNewGamesBody: "방장이 🎭로 라이어 게임·마피아를 시작해요. 배우는 언어로 설명하고 투표해요. 듣는 사람은 🔮로 추리해요.",
    whatsNewIconsTitle: "아이콘·짤 묶음",
    whatsNewIconsBody: "직접 만든 그림을 올려 모두와 나누고, 받은 아이콘을 메시지·댓글로 보내요.",
    homeTabTalk: "대화",
    talkAiTutor: "AI 튜터",
    talkAiTutorSub: "채팅으로 연습 · 📞 통화",
    talkAiCall: "AI 튜터와 통화",
    callRecordsTitle: "통화 기록",
    aiTutorBio: "사람이 아니라 AI 튜터예요. 언제든 바로 답해요. 배우는 언어로 채팅·통화하고, 쓴 문장을 고쳐 주고 하고 싶은 말을 그 언어로 알려 줘요.",
    homeTabMessages: "메시지",
    modeAi: "AI와 학습",
    modePeople: "사람과 학습",
    whatsNewRoomsTitle: "말하는 방이 생겼어요",
    whatsNewRoomsBody: "사람들과 목소리로 이야기해요. 말한 내용이 사람마다 자막으로 쌓이고, 줄을 누르면 내 언어로 번역돼요. 말이 막히면 댓글로 참여하세요.",
    whatsNewDmTitle: "프로필에서 메시지와 통화",
    whatsNewDmBody: "사진을 누르면 프로필이 열려요. 팔로우하거나 메시지를 보내고, 대화 안에서 바로 통화할 수 있어요. 통화가 끝나면 자막이 기록으로 남아요.",
    whatsNewAccountTitle: "로그인과 내 프로필",
    whatsNewAccountBody: "아이디로 로그인하면 기기를 바꿔도 기록과 구독이 이어져요. 사진·닉네임·자기소개는 방과 메시지에서 보여요.",
    whatsNewPeopleTitle: "사람 찾기",
    whatsNewPeopleBody: "최근에 온 학습자의 프로필이 보여요. 사진을 누르면 프로필이 열리고, 팔로우하거나 메시지를 보낼 수 있어요. 차단·신고도 프로필에서 해요.",
    whatsNewQuoteTitle: "남의 말을 집어서 물어보기",
    whatsNewQuoteBody: "줄을 누르면 번역 아래 ‘무슨 뜻이에요?’와 ‘쪽지로 묻기’가 있어요. 질문은 내가 배우는 언어로 채워지고, 말한 사람에게 알림이 가요.",
    whatsNewLayoutsTitle: "방을 보는 방식은 내가 골라요",
    whatsNewLayoutsBody: "방 위에서 ‘대화 보기’·‘채팅 위주’·‘통화 위주’ 등을 골라요. 자막과 채팅은 칸이 나뉘고, 아래에서 ‘말하기’·‘듣기’·‘채팅만’·‘보이스만’으로 참여 방식을 골라요.",
    whatsNewHostTitle: "방장 넘기기와 잠시 닫기",
    whatsNewHostBody: "나갈 때 ‘방장 넘기기’로 방을 이어 가게 하거나, ‘잠시 닫기’ 뒤 로비에서 ‘다시 열기’로 같은 방을 다시 열어요.",
    whatsNewHintTitle: "💡 막히면 힌트",
    whatsNewHintBody: "말하는 방에서 편한 말로 말하면(‘어.. 스물둘..’) 그 줄 아래 나에게만 ‘이렇게 말해 보세요’가 떠요. 아래 ‘힌트’에서 ‘바로 보기’·‘살짝만’·‘끄기’를 골라요.",
    whatsNewNotesTitle: "📒 My에 노트",
    whatsNewNotesBody: "‘My’ 아래 ‘노트’에 내 표현·단어·문장분석에서 물은 것이 8개 장 주제별로 모여요. 검색하고, 주제마다 ‘이 주제로 연습’. 단어장은 이제 노트 안 ‘단어장’에 있어요.",
    whatsNewBoardTitle: "📝 게시판",
    whatsNewBoardBody: "배우는 언어로 글을 올리고 댓글을 달아요. 고치고 지우는 건 쓴 사람만 할 수 있어요. 글 아래 ‘내 언어로 보기’로 번역하고, 이름을 누르면 팔로우·메시지·신고.",
    whatsNewTeamTitle: "🤝 러닝메이트·팀",
    whatsNewTeamBody: "프로필에서 ‘🤝 메이트 신청’, 단체방은 ‘팀으로 만들기’. ‘워크스페이스’에 이번 주 목표·정기 모임·같이 한 날, 물은 표현과 통화 기록이 계속 쌓여요.",
    whatsNewInviteTitle: "친구를 링크로 초대",
    whatsNewInviteBody: "‘➕ 친구 초대’로 카카오톡 등에 링크를 보내요. 받은 사람은 앱을 깔고 로그인해 이름만 정하면 바로 들어와요. 방 위 ➕는 그 방으로 초대해요.",
    whatsNewGroupsTitle: "단체방과 단체 통화",
    whatsNewGroupsBody: "‘+ 단체방’으로 팔로우한 사람을 초대해요(최대 20명). 대화 위 📞로 같이 통화하고, 끝나면 자막이 통화 기록으로 남아요.",
    whatsNewFreeTalkTitle: "🌐 자유 대화방",
    whatsNewFreeTalkBody: "새 방을 만들 때 ‘자유 대화’를 고르면 언어를 정하지 않아요. 자막은 말하는 사람마다 그 사람의 언어로 적히고, ‘언어로 찾기’에서 어떤 언어로도 나와요.",
