    homeTabMap: "Map",
    whatsNewTitle: "What’s new",
    whatsNewDone: "Got it",
    whatsNewTry: "Try it",
    whatsNewMapTitle: "A study map",
    whatsNewMapBody: "Write what you want to be able to do, and the app draws the way there in four columns: situations, expressions, vocabulary and pronunciation. The more you talk, the more it points out what you still need and what to study next.",
    whatsNewChatTitle: "Stuck? Write in your own language",
    whatsNewChatBody: "If you get stuck in chat, write in your own language. Your tutor carries on in the language you’re learning, and “Show how to say it” under your line shows how you could have said it.",
    whatsNewAskTitle: "Ask right from the sentence sheet",
    whatsNewAskBody: "Open a sentence, pick some words and tap “What does it mean here?” or “Why this form?”. You can also type your own question, and what you asked stays with that sentence.",
    whatsNewMissionTitle: "Practise a topic one task at a time",
    whatsNewMissionBody: "Open a topic on your map and tap “Practise with tasks”: you get something to do, not the answer. Write it and it’s checked and corrected, with hints one step at a time if you’re stuck.",
    whatsNewProgressTitle: "Mastered, learned, to learn",
    whatsNewProgressBody: "A phrase you produce without hints is mastered; one you managed with a hint or a correction is learned. Learned ones come back in “Review”, and using them right in chat or a call masters them.",
    whatsNewWeakTitle: "What you keep getting wrong goes on your map",
    whatsNewWeakBody: "Make the same kind of mistake twice in chat or a call and a task to practise it appears on your map, at the front of the suggested order.",
    whatsNewMeantTitle: "Calls work out what you meant",
    whatsNewMeantBody: "When a sentence comes out badly broken, the call guesses what you meant from the conversation and shows it under “Is this what you meant?”, ready to hear. Pause mid-sentence and it waits for the rest.",
    whatsNewLedgerTitle: "See the phrases you have built up",
    whatsNewLedgerBody: "“My phrases” at the top of the map gathers every phrase you met in videos, chat, calls and your word list, and shows week by week how many you have learned and can now use on your own.",
    whatsNewLinksTitle: "The tabs now talk to each other",
    whatsNewLinksBody: "Use a phrase you looked up in a video and your line says where you met it — tap to go back to that scene. The tutor also brings back phrases you have learned.",
    whatsNewPickTitle: "Choose what goes on your map",
    whatsNewPickBody: "In sentence analysis, pick a phrase and mark “I know this” or “I don’t know this”. After asking about it, tap “Put it on my map” and it becomes the first task of the topic it fits.",
    whatsNewCallToolsTitle: "Calls you can go back over",
    whatsNewCallToolsBody: "The character’s translations stay folded until you tap a line. Help for when you were stuck shows on its own, and after the call you can say any of your own lines again.",
