    whatsNewTitle: "Novedades",
    whatsNewDone: "Entendido",
    whatsNewTry: "Probar",
    whatsNewMapTitle: "Un mapa de estudio",
    whatsNewMapBody: "Escribe lo que quieres llegar a hacer y la app dibuja el camino en cuatro columnas: situaciones, expresiones, vocabulario y pronunciación. Cuanto más conversas, mejor te señala lo que te falta y qué estudiar después.",
    whatsNewChatTitle: "¿Te atascas? Escribe en tu idioma",
    whatsNewChatBody: "Si te atascas en el chat, escribe en tu idioma. El tutor sigue en el idioma que aprendes, y «Ver cómo se dice» debajo de tu línea te muestra cómo decirlo.",
    whatsNewAskTitle: "Pregunta desde el análisis de la frase",
    whatsNewAskBody: "Abre una frase, elige unas palabras y toca «¿Qué significa aquí?» o «¿Por qué esta forma?». También puedes escribir tu propia pregunta, y lo que preguntes queda guardado en esa frase.",
    whatsNewMissionTitle: "Practica un tema tarea a tarea",
    whatsNewMissionBody: "Abre un tema del mapa y toca «Practicar con tareas»: recibes algo que hacer, no la respuesta. Escríbelo y se comprueba y corrige; si te atascas, las pistas llegan paso a paso.",
    whatsNewProgressTitle: "Dominado, aprendido, por aprender",
    whatsNewProgressBody: "Lo que dices sin pistas queda dominado; lo que sacas con una pista o una corrección, aprendido. Lo aprendido vuelve en «Repasar», y usarlo bien en el chat o en una llamada lo domina.",
    whatsNewWeakTitle: "Lo que sueles fallar entra en tu mapa",
    whatsNewWeakBody: "Si cometes dos veces el mismo tipo de error en el chat o en una llamada, aparece en el mapa una tarea para practicarlo, la primera del orden sugerido.",
    whatsNewMeantTitle: "Las llamadas entienden lo que querías decir",
    whatsNewMeantBody: "Si una frase sale muy rota, la llamada deduce por la conversación lo que querías decir y lo muestra en «¿Querías decir esto?», para escucharlo. Si te paras a mitad de frase, espera a que termines.",
    whatsNewLedgerTitle: "Mira las expresiones que has ido acumulando",
    whatsNewLedgerBody: "«Mis expresiones», arriba del mapa, reúne lo que has encontrado en vídeos, chat, llamadas y tu lista de palabras, y muestra semana a semana cuánto has aprendido y ya puedes usar por tu cuenta.",
    whatsNewLinksTitle: "Las pestañas ahora se conectan",
    whatsNewLinksBody: "Si usas en el chat una expresión que buscaste en un vídeo, tu frase dice dónde la encontraste; tócala para volver a esa escena. El tutor también vuelve a usar lo que has aprendido.",
    whatsNewPickTitle: "Tú eliges qué va a tu mapa",
    whatsNewPickBody: "En el análisis de frases, elige una expresión y márcala con «La sé» o «No la sé». Después de preguntar, toca «Añadir a mi mapa» y será la primera tarea del tema que le corresponde.",
    whatsNewCallToolsTitle: "Llamadas que puedes repasar",
    whatsNewCallToolsBody: "Las traducciones del personaje quedan plegadas hasta que tocas una línea. La ayuda para cuando te atascaste aparece aparte, y al terminar puedes volver a decir cualquiera de tus frases.",
